<template>
  <AppPage title="集货发运与入库核对" subtitle="按目的国家集货、记录运输节点，并核对实际收货数量。" :capability="error ? 'degraded' : 'connected'">
    <template #action><el-button @click="load" :disabled="loading">刷新</el-button></template>
    <el-alert v-if="error" :title="error" type="error" :closable="false" class="notice" />
    <el-tabs v-model="tab" @tab-change="loadTab">
      <el-tab-pane label="集货发运" name="dispatch">
        <section class="filters">
          <el-input v-model="candidateSearch" placeholder="搜索发货单、采购单或供应商" aria-label="搜索候选发货单" @keyup.enter="candidatePage=1;loadCandidates()" />
          <el-select v-model="country" clearable filterable placeholder="目的国家" aria-label="目的国家" @change="countryChanged"><el-option v-for="c in countries" :key="c.code" :label="`${c.name} (${c.code})`" :value="c.code" /></el-select>
          <el-button @click="candidatePage=1;loadCandidates()">查询候选</el-button>
        </section>
        <div class="table-scroll" v-loading="loading"><el-table :data="candidates" border stripe @selection-change="onCandidateSelectionChange" empty-text="暂无可集货发货单">
          <el-table-column type="expand"><template #default="{row}"><DispatchProductLinesV2 :shipments="[row]"/></template></el-table-column><el-table-column type="selection" width="48" :selectable="row=>canManage && (!country || row.country_code===country)" />
          <el-table-column prop="number" label="发货单" min-width="145"/><el-table-column prop="order_number" label="采购订单" min-width="130"/><el-table-column prop="supplier_name" label="供应商" min-width="130"/><el-table-column prop="country_code" label="目的国家" width="100"/><el-table-column label="集货状态" width="115"><template #default="{row}">{{ row.delivery_mode==='factory_loading' ? '不经集货中心' : row.collection_arrived ? '已到仓' : '未到仓' }}</template></el-table-column><el-table-column label="件数" width="85"><template #default="{row}">{{ quantity(row) }}</template></el-table-column>
        </el-table></div>
        <p class="sub">可对已提交发货单建批次；集货到仓仅供参考，发运不要求先完成集货到仓。</p>
        <div class="toolbar"><el-button v-if="canManage" type="primary" :disabled="!selectedCandidates.length || busy" @click="openCreateBatch">创建发运批次</el-button></div>
        <el-pagination background layout="total, prev, pager, next" :total="candidateTotal" :current-page="candidatePage" :page-size="20" @current-change="candidatePage=$event;loadCandidates()" />
        <h3>发运批次</h3>
        <section class="filters"><el-input v-model="batchSearch" placeholder="搜索批次 / 运单号" aria-label="搜索发运批次" @keyup.enter="batchPage=1;loadBatches()"/><el-select v-model="batchStage" clearable placeholder="全部运输阶段" aria-label="运输阶段" @change="batchPage=1;loadBatches()"><el-option label="未发运" value="unmarked"/><el-option label="开船" value="departed"/><el-option label="到港" value="arrived_port"/><el-option label="到仓" value="arrived_warehouse"/></el-select><el-button @click="batchPage=1;loadBatches()">查询批次</el-button></section>
        <div class="table-scroll"><el-table :data="batches" border empty-text="暂无发运批次"><el-table-column prop="number" label="批次" min-width="150"/><el-table-column prop="country_code" label="目的国家" width="100"/><el-table-column prop="freight_number" label="运单号" min-width="130"/><el-table-column label="阶段" min-width="120"><template #default="{row}">{{ stageLabel(row.stage) }}</template></el-table-column><el-table-column label="发货单数" width="100"><template #default="{row}">{{ row.shipments?.length ?? row.shipment_count ?? '—' }}</template></el-table-column><el-table-column label="操作" width="100"><template #default="{row}"><el-button link type="primary" @click="openBatch(row)">查看 / 更新</el-button></template></el-table-column></el-table></div>
        <el-pagination background layout="total, prev, pager, next" :total="batchTotal" :current-page="batchPage" :page-size="20" @current-change="batchPage=$event;loadBatches()" />
      </el-tab-pane>
      <el-tab-pane label="入库核对" name="inbound">
        <section class="filters"><el-input v-model="inboundSearch" placeholder="搜索入库单 / 批次" aria-label="搜索入库单" @keyup.enter="inboundPage=1;loadInbounds()"/><el-select v-model="inboundStatus" clearable placeholder="全部入库状态" aria-label="入库状态" @change="inboundPage=1;loadInbounds()"><el-option label="待核对" value="draft"/><el-option label="已确认" value="confirmed"/></el-select><el-button @click="inboundPage=1;loadInbounds()">查询</el-button></section>
        <div class="table-scroll"><el-table :data="inbounds" border empty-text="暂无入库单"><el-table-column prop="number" label="入库单" min-width="150"/><el-table-column prop="batch_number" label="发运批次" min-width="145"/><el-table-column prop="warehouse_name" label="目的仓" min-width="130"/><el-table-column label="状态" width="110"><template #default="{row}">{{ inboundStatusLabel(row.status) }}</template></el-table-column><el-table-column label="操作" width="100"><template #default="{row}"><el-button link type="primary" @click="openInbound(row)">核对 / 查看</el-button></template></el-table-column></el-table></div>
        <el-pagination background layout="total, prev, pager, next" :total="inboundTotal" :current-page="inboundPage" :page-size="20" @current-change="inboundPage=$event;loadInbounds()" />
      </el-tab-pane>
    </el-tabs>

    <el-dialog v-model="batchDialog" title="创建发运批次" width="min(680px, 96vw)" class="sc2-scroll-dialog" top="4vh" :close-on-click-modal="!busy" :close-on-press-escape="!busy" :show-close="!busy">
      <p>已选 {{ selectedCandidates.length }} 张发货单 · 目的国家 {{ selectedCountry || '—' }}</p>
      <section v-for="shipment in selectedCandidates" :key="shipment.id" class="allocation-section"><h4>{{ shipment.number }} · 本批集货数量</h4><div v-for="line in shipment.lines || []" :key="lineId(line)" class="allocation-row"><span><strong>{{ line.sku || line.sku_code || 'SKU' }}</strong> · {{ line.product_name || '' }} · 可分配 {{ remainingQuantity(line) }}</span><el-input-number :model-value="createAllocations[lineId(line)] ?? remainingQuantity(line)" :min="0" :max="remainingQuantity(line)" :precision="0" :controls="false" :disabled="busy" :aria-label="`${shipment.number} ${line.sku || 'SKU'} 本批集货数量`" @update:model-value="createAllocations[lineId(line)]=$event"/></div></section>
      <el-form-item label="货代"><el-select v-model="batchForm.freight_company_id" filterable placeholder="选择货代" :disabled="busy"><el-option v-for="f in freightCompanies" :key="f.id" :label="`${f.name} (${f.code})`" :value="f.id" /></el-select></el-form-item>
      <FreightPlanFieldsV2 v-if="batchDialog" :form="batchForm" :country-code="selectedCountry" :warehouses="warehouses" :disabled="busy || !canManage"/>
      <el-form-item label="预计到仓日期"><el-date-picker v-model="batchForm.expected_warehouse_date" type="date" value-format="YYYY-MM-DD" :disabled="busy || !canManage"/></el-form-item>
      <el-form-item label="运单号"><el-input v-model="batchForm.freight_number" :disabled="busy"/></el-form-item><el-form-item label="备注"><el-input v-model="batchForm.notes" type="textarea" :disabled="busy"/></el-form-item><el-alert v-if="formError" :title="formError" type="error" :closable="false"/>
      <template #footer><el-button :disabled="busy" @click="batchDialog=false">取消</el-button><el-button type="primary" :loading="busy" :disabled="busy || !canManage" @click="createBatch">创建批次</el-button></template>
    </el-dialog>

    <el-drawer v-model="batchOpen" :before-close="closeDrawer" :close-on-press-escape="!busy" :close-on-click-modal="!busy" :title="currentBatch?.number || '发运批次'" size="min(900px, 96vw)">
      <template v-if="currentBatch"><el-alert v-if="currentBatch.status==='cancelled'" title="批次已取消" type="warning" :closable="false"/><el-descriptions border :column="2"><el-descriptions-item label="目的国家">{{ currentBatch.country_code }}</el-descriptions-item><el-descriptions-item label="阶段">{{ stageLabel(currentBatch.stage) }}</el-descriptions-item><el-descriptions-item label="状态">{{ currentBatch.status==='cancelled'?'已取消':'有效' }}</el-descriptions-item><el-descriptions-item label="货代">{{ currentBatch.freight_company_name || '—' }}</el-descriptions-item><el-descriptions-item label="唛头">{{ currentBatch.shipping_marks || '—' }}</el-descriptions-item><el-descriptions-item label="选定货代时每方费用快照">{{ snapshotAmount(currentBatch.fee_per_cbm_snapshot) }}</el-descriptions-item><el-descriptions-item label="选定货代时税费点数快照">{{ snapshotPercent(currentBatch.tax_percent_snapshot) }}</el-descriptions-item></el-descriptions><CostSettlementLinkV2 kind="batch" :id="currentBatch.id" :version="currentBatch.version" @updated="target=>currentBatch={...currentBatch,...target}"/><section v-if="currentBatch.status==='cancelled'" class="batch-history"><strong>取消记录</strong><p v-for="event in (currentBatch.history||[]).filter(e=>e.action==='batch_cancelled')" :key="event.id">{{ event.payload?.reason || '未提供原因' }} · {{ dateLabel(event.created_at) }}</p></section>
        <template v-if="currentBatch.stage==='unmarked' && currentBatch.status!=='cancelled'"><el-form-item label="货代"><el-select v-model="batchEdit.freight_company_id" :disabled="!canManage || busy"><el-option v-for="f in freightCompanies" :key="f.id" :label="f.name" :value="f.id"/></el-select></el-form-item><el-form-item label="运单号"><el-input v-model="batchEdit.freight_number" :disabled="!canManage || busy"/></el-form-item><el-form-item label="备注"><el-input v-model="batchEdit.notes" type="textarea" :disabled="!canManage || busy"/></el-form-item><el-form-item label="预计到仓日期"><el-date-picker v-model="batchEdit.expected_warehouse_date" type="date" value-format="YYYY-MM-DD" :disabled="!canManage || busy"/></el-form-item></template>
        <section v-if="currentBatch.status==='active' && currentBatch.stage!=='arrived_warehouse'" class="eta-panel"><strong>预计到仓：{{ dateOnly(currentBatch.expected_warehouse_date) }}</strong><template v-if="currentBatch.stage!=='unmarked' && canManage"><el-date-picker v-model="etaDate" type="date" value-format="YYYY-MM-DD" :disabled="busy"/><el-input v-model="etaReason" placeholder="更新原因必填" aria-label="预计到仓日期更新原因" :disabled="busy"/><el-button :disabled="busy" :loading="busy" @click="saveExpectedDate">更新预计到仓日期</el-button></template></section>
        <el-descriptions border :column="2"><el-descriptions-item label="运输渠道">{{ currentBatch.freight_quote_snapshot?.name || '沿用公司默认价' }}</el-descriptions-item><el-descriptions-item label="报价版本">{{ currentBatch.freight_quote_snapshot?.quote ? `v${currentBatch.freight_quote_snapshot.quote.sequence}` : '未选渠道报价' }}</el-descriptions-item><el-descriptions-item label="计划目的仓">{{ currentBatch.planned_warehouse_name || '未指定' }}</el-descriptions-item><el-descriptions-item label="实际柜号 / 柜数">{{ currentBatch.container_number || '未登记' }} / {{ currentBatch.container_count || 1 }}</el-descriptions-item></el-descriptions>
        <FreightPlanFieldsV2 v-if="currentBatch.stage==='unmarked' && currentBatch.status!=='cancelled'" :key="currentBatch.id" :form="batchEdit" :snapshot="currentBatch" :country-code="currentBatch.country_code" :warehouses="warehouses" :disabled="busy || !canManage"/>
        <div class="table-scroll"><el-table :data="currentBatch.shipments || []" border><el-table-column prop="number" label="发货单"/><el-table-column prop="order_number" label="采购单"/><el-table-column prop="supplier_name" label="供应商"/><el-table-column prop="country_code" label="目的国家"/></el-table></div>
        <h3>批次商品明细</h3><DispatchProductLinesV2 :shipments="currentBatch.shipments || []"/><template v-if="currentBatch.stage==='unmarked' && currentBatch.status!=='cancelled' && canManage"><el-form-item label="批次成员"><el-select v-model="memberSelection" multiple filterable placeholder="选择同国家候选发货单" :disabled="busy" @update:model-value="syncMemberAllocations"><el-option v-for="s in memberOptions" :key="s.id" :label="`${s.number} · ${s.supplier_name||''}`" :value="s.id"/></el-select></el-form-item><section v-for="row in memberAllocationRows" :key="`${row.shipment.id}-${lineId(row.line)}`" class="allocation-row"><DocumentProductImageV2 class="allocation-product-image" :image-path="row.line.image_preview_url || ''" :alt="`${row.line.sku || row.line.sku_code || ''} 商品图片`"/><div class="allocation-product"><DocumentSkuV2 :sku="row.line.sku || row.line.sku_code" :legacy-sku-code="row.line.legacy_sku_code"/><small>{{ row.shipment.number }} · {{ row.line.product_name || '' }}</small><div class="allocation-quantities"><span>原发货 {{ row.line.source_quantity ?? row.line.quantity ?? '—' }}</span><span>已分配 {{ row.line.allocated_quantity ?? '—' }}</span><span>剩余 {{ row.line.remaining_quantity ?? row.max }}</span><span>本批数量</span></div></div><el-input-number :model-value="memberAllocations[lineId(row.line)] ?? row.defaultQuantity" :min="0" :max="row.max" :precision="0" :controls="false" :disabled="busy" :aria-label="`${row.shipment.number} ${row.line.sku || 'SKU'} 本批集货数量`" @update:model-value="memberAllocations[lineId(row.line)]=$event"/></section><el-form-item label="成员变更原因"><el-input v-model="memberReason" placeholder="必填" :disabled="busy"/></el-form-item><el-button :disabled="busy" :loading="busy" @click="saveMembers">更新批次成员</el-button><el-form-item label="取消原因"><el-input v-model="cancelReason" placeholder="必填" :disabled="busy"/></el-form-item><el-button type="danger" :disabled="busy" :loading="busy" @click="cancelBatch">取消未发运批次</el-button></template>
        <h3>批次运输节点</h3><p class="sub">按批次标记，自动同步到本批次各张发货单的对应数量。</p><div class="dates"><p>开船：{{ dateLabel(currentBatch.logistics_dates?.departed_at) }}</p><p>到港：{{ dateLabel(currentBatch.logistics_dates?.arrived_port_at) }}</p><p>到仓：{{ dateLabel(currentBatch.logistics_dates?.arrived_warehouse_at) }}</p></div>
        <template v-if="currentBatch.status!=='cancelled' && canManage && recordedDateStages.length"><el-form-item label="修正已记录节点"><el-select v-model="dateStage" :disabled="busy"><el-option v-for="stage in recordedDateStages" :key="stage" :label="stageLabel(stage)" :value="stage"/></el-select></el-form-item><el-form-item label="正确发生时间"><el-date-picker v-model="correctedAt" type="datetime" value-format="YYYY-MM-DDTHH:mm:ss" :disabled="busy"/></el-form-item><el-form-item label="修正原因"><el-input v-model="dateReason" placeholder="必填" :disabled="busy"/></el-form-item><el-button :disabled="busy" :loading="busy" @click="correctDate">保存日期修正</el-button></template>
        <el-form-item v-if="nextStage && currentBatch.status!=='cancelled'" label="节点发生时间"><el-date-picker v-model="occurredAt" type="datetime" value-format="YYYY-MM-DDTHH:mm:ss" format="YYYY-MM-DD HH:mm:ss" :disabled="!canManage || busy"/></el-form-item>
        <el-form-item v-if="currentBatch.stage==='arrived_warehouse' && !currentBatch.inbound_id" label="目的仓"><el-select v-model="warehouseId" :disabled="!canManage || busy"><el-option v-for="w in batchWarehouses" :key="w.id" :label="w.name" :value="w.id"/></el-select></el-form-item>
        <el-form-item v-if="currentBatch.stage==='arrived_warehouse' && !currentBatch.inbound_id && currentBatch.planned_warehouse_id && String(warehouseId)!==String(currentBatch.planned_warehouse_id)" label="实际改仓原因"><el-input v-model="makeInboundReason" :disabled="!canManage || busy" placeholder="实际入库仓与计划仓不同时必填" aria-label="实际改仓原因"/></el-form-item>
        <el-alert v-if="formError" :title="formError" type="error" :closable="false" />
      </template>
      <template #footer><div class="actions"><el-button :disabled="busy" @click="batchOpen=false">关闭</el-button><el-button v-if="currentBatch?.stage==='unmarked' && currentBatch?.status!=='cancelled' && canManage" :disabled="busy" :loading="busy" @click="saveBatch">保存批次信息</el-button><el-button v-if="nextStage && currentBatch?.status!=='cancelled' && canManage" type="primary" :disabled="busy" :loading="busy" @click="advanceStage">{{ stageLabel(nextStage) }}</el-button><el-button v-if="currentBatch?.inbound_id" type="success" :disabled="busy" @click="tab='inbound';loadInbounds();openInbound({id:currentBatch.inbound_id})">查看入库单</el-button><el-button v-if="currentBatch?.stage==='arrived_warehouse' && !currentBatch.inbound_id && canManage" type="primary" :disabled="busy" :loading="busy" @click="makeInbound">生成入库草稿</el-button></div></template>
    </el-drawer>

    <el-drawer v-model="inboundOpen" :before-close="closeDrawer" :close-on-press-escape="!busy" :close-on-click-modal="!busy" :title="currentInbound?.number || '入库单核对'" size="min(1050px, 96vw)">
      <template v-if="currentInbound"><el-alert v-if="currentInbound.status==='confirmed'" title="本模块入库流水已记账；第三方仓库存以其回传为准" type="info" :closable="false" class="notice"/>
        <el-descriptions border :column="2"><el-descriptions-item label="发运批次">{{ currentInbound.batch_number }}</el-descriptions-item><el-descriptions-item label="目的国家">{{ currentInbound.country_code }}</el-descriptions-item><el-descriptions-item label="目的仓">{{ currentInbound.warehouse_name }}</el-descriptions-item><el-descriptions-item label="状态">{{ currentInbound.status==='confirmed'?'已确认':'待核对' }}</el-descriptions-item></el-descriptions><CostSettlementLinkV2 kind="inbound" :id="currentInbound.id" :version="currentInbound.version" @updated="target=>currentInbound={...currentInbound,...target}"/>
        <el-form-item label="目的仓"><el-select v-model="inboundForm.warehouse_id" :disabled="!canManage || busy || !!pendingConfirmation || currentInbound.status!=='draft'"><el-option v-for="w in inboundWarehouses" :key="w.id" :label="w.name" :value="w.id"/></el-select></el-form-item><el-form-item label="备注"><el-input v-model="inboundForm.notes" type="textarea" :disabled="!canManage || busy || !!pendingConfirmation || currentInbound.status!=='draft'"/></el-form-item>
        <el-form-item v-if="currentInbound.status==='draft' && String(inboundForm.warehouse_id)!==String(currentInbound.warehouse_id)" label="入库仓变更原因"><el-input v-model="inboundForm.reason" :disabled="!canManage || busy || !!pendingConfirmation" placeholder="更换实际入库仓时必填" aria-label="入库仓变更原因"/></el-form-item>
        <div class="table-scroll"><el-table :data="inboundForm.lines" border><el-table-column prop="shipment_number" label="发货单" min-width="125"/><el-table-column prop="order_number" label="采购单" min-width="125"/><el-table-column prop="supplier_name" label="供应商" min-width="120"/><el-table-column label="商品图片" width="112"><template #default="{row}"><DocumentProductImageV2 :image-path="row.image_preview_url || ''" :alt="`${row.sku || ''} 商品图片`"/></template></el-table-column><el-table-column label="SKU" min-width="180"><template #default="{row}"><DocumentSkuV2 :sku="row.sku" :legacy-sku-code="row.legacy_sku_code"/></template></el-table-column><el-table-column prop="product_name" label="商品" min-width="130"/><el-table-column prop="expected_quantity" label="应收" width="80"/><el-table-column label="实收" width="130"><template #default="{row}"><el-input-number v-if="currentInbound.status==='draft' && canManage" v-model="row.received_quantity" :min="0" :precision="0" :controls="false" :disabled="busy || !!pendingConfirmation"/><span v-else>{{ row.received_quantity }}</span></template></el-table-column><el-table-column label="差异说明" min-width="170"><template #default="{row}"><el-input v-if="currentInbound.status==='draft' && canManage" v-model="row.difference_note" :disabled="busy || !!pendingConfirmation"/><span v-else>{{ row.difference_note || '—' }}</span></template></el-table-column></el-table></div>
        <el-button v-if="currentInbound.status==='draft' && canManage" link :disabled="busy || !!pendingConfirmation" @click="fillExpected">按应收数量填入</el-button><el-alert v-if="formError" :title="formError" type="error" :closable="false"/><el-alert v-if="currentInbound.status==='confirmed'" :title="`入库流水号：${currentInbound.stock_receipt_ref || '—'}`" type="success" :closable="false"/>
        <section v-if="currentInbound.status==='confirmed' && canViewWms" class="wms-reconciliation"><h3>真实 WMS 入库对账</h3><el-alert v-if="wmsError" :title="wmsError" type="warning" :closable="false"/><div v-for="local in wmsReconciliation" :key="local.receipt_line_id" class="wms-line"><div><strong>{{ local.sku }}</strong> · 本系统实收 {{ local.local_received_quantity }}，已登记 {{ local.allocated_quantity }}，有效匹配 {{ local.valid_quantity }}，可关联 {{ local.remaining_quantity }}</div><el-button v-if="canManage && local.remaining_quantity>0" :disabled="busy" @click="openWmsCandidates(local)">选择 WMS 行</el-button><div v-for="allocation in local.allocations" :key="allocation.id" class="wms-allocation"><span>{{ allocation.status==='matched'?'已匹配':'待核对' }} · {{ allocation.quantity }} 件 · {{ allocation.wms_line ? `${allocation.wms_line.external_inbound_id} / ${allocation.wms_line.external_line_id}` : 'WMS 来源不可见或事实已变化' }}</span><template v-if="canManage"><el-input v-model="wmsRemovalReasons[allocation.id]" placeholder="解除原因必填" :disabled="busy"/><el-button type="danger" :disabled="busy" @click="removeWmsAllocation(local,allocation)">解除关联</el-button></template></div></div></section>
