async function createBatch(){if(!canManage.value||busy.value)return;formError.value='';if(!selectedCandidates.value.length||!selectedCountry.value){formError.value='请选择同一目的国家的发货单。';return;}if(country.value&&selectedCountry.value!==country.value){formError.value='所选发货单与目的国家筛选不一致。';return;}if(!batchForm.freight_company_id||!freightCompanies.value.some(f=>String(f.id)===String(batchForm.freight_company_id)&&(!f.country_code||f.country_code===selectedCountry.value))){formError.value='请选择适用于该目的国家的货代。';return;}const allocations=[];for(const shipment of selectedCandidates.value){const lines=shipment.lines||[],positive=lines.filter(line=>Number(createAllocations[lineId(line)]??remainingQuantity(line))>0);if(!positive.length){formError.value=`${shipment.number} 至少需要一个正数量 SKU。`;return;}for(const line of positive){const id=lineId(line),amount=Number(createAllocations[id]??remainingQuantity(line));if(id==null||!Number.isInteger(amount)||amount<0||amount>remainingQuantity(line)){formError.value='请检查 SKU 集货数量，数量必须为不超过可分配量的整数。';return;}allocations.push({shipment_line_id:id,quantity:amount});}}busy.value=true;try{const shipment_ids=selectedCandidates.value.map(s=>s.id),shipment_versions=selectedCandidates.value.map(s=>({id:s.id,version:s.version})),body={shipment_ids,shipment_versions,allocations,freight_company_id:batchForm.freight_company_id,freight_number:batchForm.freight_number,notes:batchForm.notes,...planPayload(batchForm)};const result=await mutate('create-batch',body,key=>api.createDispatchBatch(body,key));batchDialog.value=false;selectedCandidates.value=[];Object.assign(batchForm,blankPlan());for(const key of Object.keys(createAllocations))delete createAllocations[key];await Promise.all([loadCandidates(),loadBatches()]);await openBatch(result); }catch(e){formError.value=e.message||'创建批次失败，所选内容已保留。';}finally{busy.value=false;}}
