async function saveExpectedDate(){const batch=currentBatch.value;if(!canManage.value||busy.value||!batch||batch.stage==='arrived_warehouse')return;formError.value='';if(!etaReason.value.trim()){formError.value='请填写预计到仓日期更新原因。';return;}const body={expected_version:batch.version,expected_warehouse_date:etaDate.value||null,reason:etaReason.value.trim()};busy.value=true;try{currentBatch.value=await mutate(`eta-${batch.id}`,body,key=>api.updateDispatchExpectedWarehouseDate(batch.id,body,key));etaReason.value='';await loadBatches();}catch(e){formError.value=e.message||'预计到仓日期更新失败';}finally{busy.value=false;}}
function toAwareIso(value){if(!value)return '';const local=/([zZ]|[+-]\d{2}:?\d{2})$/.test(value)?new Date(value):new Date(value.replace(' ','T'));return Number.isNaN(local.getTime())?'':local.toISOString();}
async function advanceStage(){if(!canManage.value||!nextStage.value||busy.value)return;formError.value='';if(currentBatch.value.stage==='unmarked'&&batchEditFingerprint()!==savedBatchFingerprint()&&!await saveBatch())return;const occurred_at=toAwareIso(occurredAt.value);if(!occurred_at){formError.value='请选择有效的节点发生时间。';return;}try{await ElMessageBox.confirm(`记录“${stageLabel(nextStage.value)}”节点？`,'确认运输节点',{type:'warning'});}catch{return;}const body={expected_version:currentBatch.value.version,stage:nextStage.value,occurred_at};busy.value=true;try{currentBatch.value=await mutate(`stage-${currentBatch.value.id}`,body,key=>api.advanceDispatchBatch(currentBatch.value.id,body,key));occurredAt.value='';await loadBatches();}catch(e){formError.value=e.message||'更新节点失败';}finally{busy.value=false;}}
async function makeInbound(){if(!canManage.value||busy.value||!warehouseId.value)return;formError.value='';busy.value=true;try{if(!warehouses.value.some(w=>String(w.id)===String(warehouseId.value)&&w.country_code===currentBatch.value.country_code))await loadOptions(currentBatch.value.country_code);
  const warehouse=warehouses.value.find(w=>String(w.id)===String(warehouseId.value));if(!warehouse||warehouse.country_code!==currentBatch.value.country_code){formError.value='请选择与目的国家一致的仓库。';return;}if(currentBatch.value.planned_warehouse_id&&String(warehouseId.value)!==String(currentBatch.value.planned_warehouse_id)&&!makeInboundReason.value.trim()){formError.value='实际入库仓与计划仓不同时，请填写改仓原因。';return;}const body={expected_version:currentBatch.value.version,warehouse_id:warehouseId.value,...(makeInboundReason.value.trim()?{reason:makeInboundReason.value.trim()}:{})};const result=await mutate(`inbound-${currentBatch.value.id}`,body,key=>api.generateInbound(currentBatch.value.id,body,key));currentBatch.value.inbound_id=result.id;await loadInbounds();await openInbound(result);}catch(e){formError.value=e.message||'生成入库草稿失败';}finally{busy.value=false;}}
async function loadWmsReconciliation(){if(!currentInbound.value||!canViewWms.value||currentInbound.value.status!=='confirmed')return;wmsError.value='';try{wmsReconciliation.value=rows(unwrap(await api.fetchWmsReconciliation(currentInbound.value.id)));}catch(e){wmsError.value=e.message||'WMS 对账信息加载失败';}}
async function searchWmsCandidates(){if(!currentInbound.value||!wmsTargetLine.value)return;wmsError.value='';try{wmsCandidates.value=rows(unwrap(await api.fetchWmsCandidates(currentInbound.value.id,{inbound_line_id:wmsTargetLine.value.inbound_line_id,search:wmsSearch.value})));}catch(e){wmsCandidates.value=[];wmsError.value=e.message||'WMS 候选行加载失败';}}
async function openWmsCandidates(local){if(!canManage.value||!currentInbound.value)return;wmsError.value='';wmsTargetLine.value=local;wmsSelectedId.value=null;wmsQuantity.value=1;wmsNotes.value='';wmsSearch.value='';wmsDialog.value=true;await searchWmsCandidates();}
async function createWmsLink(){if(!canManage.value||busy.value||!wmsSelectedId.value||!currentInbound.value||!wmsTargetLine.value)return;const selected=wmsCandidates.value.find(row=>row.id===wmsSelectedId.value);if(!selected)return;const maximum=Math.min(wmsTargetLine.value.remaining_quantity,selected.remaining_quantity);if(!Number.isInteger(wmsQuantity.value)||wmsQuantity.value<1||wmsQuantity.value>maximum){wmsError.value='关联数量超过本地或 WMS 可用实收数量。';return;}const body={inbound_line_id:wmsTargetLine.value.inbound_line_id,wms_line_id:selected.id,quantity:wmsQuantity.value,notes:wmsNotes.value};busy.value=true;try{await mutate(`wms-link-${currentInbound.value.id}`,body,key=>api.createWmsAllocation(currentInbound.value.id,body,key));wmsDialog.value=false;await loadWmsReconciliation();}catch(e){wmsError.value=e.message||'WMS 关联失败';}finally{busy.value=false;}}
async function removeWmsAllocation(local,allocation){const reason=String(wmsRemovalReasons[allocation.id]||'').trim();if(!canManage.value||busy.value||!reason){wmsError.value='解除关联必须填写原因。';return;}const body={expected_version:allocation.version,reason};busy.value=true;try{await mutate(`wms-unlink-${allocation.id}`,body,key=>api.deactivateWmsAllocation(currentInbound.value.id,allocation.id,body,key));delete wmsRemovalReasons[allocation.id];await loadWmsReconciliation();}catch(e){wmsError.value=e.message||'解除 WMS 关联失败';}finally{busy.value=false;}}
async function openInbound(row){inboundOpen.value=true;currentInbound.value=null;formError.value='';wmsError.value='';wmsReconciliation.value=[];savedReceiptFingerprint.value='';pendingConfirmation.value=null;try{const detail=unwrap(await api.fetchInboundOrder(row.id));currentInbound.value=detail;loadOptions(detail.country_code).catch(e=>errorText('目的国家选项加载失败',e));Object.assign(inboundForm,{warehouse_id:detail.warehouse_id,notes:detail.notes||'',reason:'',lines:(detail.lines||[]).map(l=>({...l,received_quantity:l.received_quantity==null?null:Number(l.received_quantity),difference_note:l.difference_note||''}))});savedReceiptFingerprint.value=receiptFingerprint();await loadWmsReconciliation();}catch(e){formError.value=e.message||'读取入库单失败';}}
function validateReceipt(){if(inboundForm.lines.some(l=>l.received_quantity==null||!Number.isInteger(Number(l.received_quantity))||Number(l.received_quantity)<0)){formError.value='请为每个商品填写 0 或更大的整数实收数量。';return false;}if(inboundForm.lines.some(l=>Number(l.received_quantity)!==Number(l.expected_quantity)&&!String(l.difference_note||'').trim())){formError.value='实收与应收不同的每行都必须填写差异说明。';return false;}return true;}
function receiptFingerprint(){return JSON.stringify({warehouse_id:inboundForm.warehouse_id,notes:inboundForm.notes,lines:inboundForm.lines.map(l=>({id:l.id,received_quantity:l.received_quantity==null?null:Number(l.received_quantity),difference_note:l.difference_note||''}))});}
function receiptBody(){return {expected_version:currentInbound.value.version,warehouse_id:inboundForm.warehouse_id,notes:inboundForm.notes,...(inboundForm.reason.trim()?{reason:inboundForm.reason.trim()}:{}),lines:inboundForm.lines.map(l=>({id:l.id,received_quantity:Number(l.received_quantity),difference_note:l.difference_note||''}))};}
async function saveInbound(){if(!canManage.value||currentInbound.value?.status!=='draft'||busy.value||pendingConfirmation.value)return false;formError.value='';if(!validateReceipt())return false;if(String(inboundForm.warehouse_id)!==String(currentInbound.value.warehouse_id)&&!inboundForm.reason.trim()){formError.value='更换入库仓时，请填写变更原因。';return false;}if(receiptFingerprint()===savedReceiptFingerprint.value)return true;const body=receiptBody();busy.value=true;try{currentInbound.value=await mutate(`receipt-${currentInbound.value.id}`,body,key=>api.updateInboundOrder(currentInbound.value.id,body,key));inboundForm.lines=(currentInbound.value.lines||[]).map(l=>({...l,received_quantity:l.received_quantity==null?null:Number(l.received_quantity),difference_note:l.difference_note||''}));inboundForm.reason='';savedReceiptFingerprint.value=receiptFingerprint();await loadInbounds();return true;}catch(e){formError.value=e.message||'保存核对失败';return false;}finally{busy.value=false;}}
async function confirmInbound(){if(!canManage.value||currentInbound.value?.status!=='draft'||busy.value)return;formError.value='';if(!pendingConfirmation.value){if(!validateReceipt())return;try{await ElMessageBox.confirm('确认收货并生成本模块入库流水？确认后数量将记账且无法修改。','确认入库',{type:'warning'});}catch{return;}if(!await saveInbound())return;pendingConfirmation.value={fingerprint:savedReceiptFingerprint.value,body:{expected_version:currentInbound.value.version}};}
  if(pendingConfirmation.value.fingerprint!==savedReceiptFingerprint.value){formError.value='核对内容已变化，请重新保存后再确认。';pendingConfirmation.value=null;return;}
  const body=pendingConfirmation.value.body;busy.value=true;try{currentInbound.value=await mutate(`confirm-${currentInbound.value.id}`,body,key=>api.confirmInboundOrder(currentInbound.value.id,body,key));pendingConfirmation.value=null;Object.assign(inboundForm,{warehouse_id:currentInbound.value.warehouse_id,notes:currentInbound.value.notes||'',lines:(currentInbound.value.lines||[]).map(l=>({...l}))});await loadInbounds();}catch(e){formError.value=e.message||'确认入库失败；可重试同一确认操作。';}finally{busy.value=false;}}
function fillExpected(){if(currentInbound.value?.status==='draft'&&canManage.value)inboundForm.lines.forEach(l=>{l.received_quantity=Number(l.expected_quantity);});}
defineExpose({openBatch,openInbound,makeInbound,createBatch,saveInbound,confirmInbound,advanceStage,saveMembers,cancelBatch,correctDate,saveExpectedDate,openWmsCandidates,searchWmsCandidates,createWmsLink,removeWmsAllocation,candidates,selectedCandidates,createAllocations,memberAllocations,batchForm,batchEdit,inboundForm,wmsReconciliation,wmsCandidates,wmsTargetLine,wmsSelectedId,wmsQuantity,wmsNotes,wmsSearch,wmsDialog,wmsError,etaDate,etaReason,occurredAt,warehouseId,makeInboundReason,memberSelection,memberReason,cancelReason,dateStage,correctedAt,dateReason});
async function openRouteTarget(){
  const query=route?.query||{};
  if(query.inbound_id && /^\d+$/.test(String(query.inbound_id))){tab.value='inbound';await openInbound({id:Number(query.inbound_id)});}
  else if(query.batch_id && /^\d+$/.test(String(query.batch_id))){tab.value='dispatch';await openBatch({id:Number(query.batch_id)});}
  else if(query.tab==='inbound'){tab.value='inbound';await loadInbounds();}
}
watch(()=>route?.fullPath,()=>openRouteTarget());
onMounted(async()=>{await load();await openRouteTarget();});
</script>

